0px;background:#061525;margin-top:8px}.danger{border-left:4px solid #ff6378;padding:10px;background:#1d080d;margin-top:8px}.target{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}.concept{border-left:4px solid #b47cff;padding:10px;background:#140d22;margin-top:8px}.final{font-size:19px;font-weight:900;white-space:pre-line;line-height:1.55}.error{color:#ff6378;margin-top:10px}.legend{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.legend span{padding:5px 8px;border-radius:7px;background:#101e2b;border:1px solid #29435b;font-size:12px}.modal{display:none;position:fixed;z-index:99;inset:0;background:#000e;align-items:center;justify-content:center;padding:15px}.modal.open{display:flex}.modal img{max-width:96vw;max-height:92vh}.close{position:fixed;right:20px;top:10px;font-size:35px;cursor:pointer}.tutorialBox{margin-top:10px;border:1px solid #29435b;padding:12px;border-radius:10px;background:#07111b}.tutorialTitle{color:#27e0a0;font-weight:900}..currentBox{border-left:4px solid #fff;padding:10px;background:#101820;margin-top:8px}.scenarioBox{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}.decision{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:12px}.decision div{padding:10px;border:1px solid #29435b;background:#07111b;border-radius:9px;text-align:center}.decision b{display:block;color:#27e0a0;font-size:12px;margin-bottom:5px}.smartNote{margin-top:8px;color:#7890a4;font-size:12px}.zoneKey{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.zoneKey span{font-size:11px;padding:5px 7px;border-radius:6px;border:1px solid #29435b;background:#07111b}.headline{font-size:22px;font-weight:900;margin:4px 0}.confidence{font-size:12px;color:#9fb4c7}.stepLine{display:flex;gap:8px;align-items:flex-start;margin-top:8px}.stepNo{min-width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#27e0a0;color:#03120d;font-weight:900}.analysisGrid{display:grid;grid-template-columns:1.3fr .7fr;gap:14px}.sectionTitle{font-weight:900;color:#27e0a0}.fvgText{color:#55a9ff}.obText{color:#27e0a0}.trendText{color:#ffd166}@media(max-width:1000px){.hero,.uploadGrid,.charts,.analysisGrid{grid-template-columns:1fr}.story{grid-template-columns:repeat(2,1fr)}.decision{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.wrap{padding:9px}.top{align-items:flex-start;flex-direction:column}.story{grid-template-columns:1fr}.decision{grid-template-columns:1fr}.chartHead{flex-direction:column}}
