<section id="result" class="result">
<div class="card"><div class="headline" id="title"></div><div class="confidence" id="confidence"></div><div id="final" class="final"></div><div id="current" class="currentBox"></div><div id="reason" class="muted"></div><div id="confluence" class="muted"></div><div class="decision"><div><b>ENTRY</b><span id="dEntry">—</span></div><div><b>CONFIRM</b><span id="dConfirm">—</span></div><div><b>INVALIDATION</b><span id="dInvalid">—</span></div><div><b>TP1</b><span id="dTp1">—</span></div><div><b>TP2</b><span id="dTp2">—</span></div></div></div>
