</section></div>
<div id="modal" class="modal"><span class="close" id="close">×</span><img id="big"></div>
<script>
const slots=document.getElementById('slots');
for(let i=0;i<4;i++){const s=document.createElement('div');s.className='slot';s.innerHTML='<b>CHART '+(i+1)+'</b><select class="tf"><option>H4</option><option>H1</option><option>M30</option><option>M15</option><option>M5</option><option>M1</option><option>D1</option><option>UNKNOWN</option></select><input class="file" type="file" accept="image/png,image/jpeg,image/webp"><img class="thumb"><small class="size" style="display:block;color:#71869a;margin-top:6px"></small>';slots.appendChild(s);const f=s.querySelector('.file'),im=s.querySelector('.thumb'),sz=s.querySelector('.size');f.addEventListener('change',()=>{if(f.files&&f.files[0]){im.src=URL.createObjectURL(f.files[0]);im.style.display='block';sz.textContent='Selected: '+(f.files[0].size/1048576).toFixed(2)+' MB'}})}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function openBig(src){document.getElementById('big').src=src;document.getElementById('modal').classList.add('open')}
document.getElementById('close').onclick=()=>document.getElementById('modal').classList.remove('open');document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')};
function compress(file){return new Promise((resolve,reject)=>{const im=new Image(),u=URL.createObjectURL(file);im.onload=()=>{let w=im.naturalWidth,h=im.naturalHeight,m=Math.max(w,h);if(m>1600){w=Math.round(w*1600/m);h=Math.round(h*1600/m)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return reject(new Error('Could not prepare image'));resolve(new File([b],'chart.jpg',{type:'image/jpeg'}))},'image/jpeg',.78)};im.onerror=()=>reject(new Error('Could not read image'));im.src=u})}
function colorFor(type){if(!type)return '#fff';if(['OB_BULL','ENTRY','TARGET1','TARGET2','HL'].includes(type))return '#27e0a0';if(['OB_BEAR','INVALIDATION','LH'].includes(type))return '#ff6378';if(['FVG','CONFIRMATION','BOS','CHoCH','DISPLACEMENT'].includes(type))return '#55a9ff';if(['LIQUIDITY','SWEEP','TARGET','TRENDLINE','SUPPORT','RESISTANCE'].includes(type))return '#ffd166';return '#fff'}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function rectHit(a,b,pad=8){return !(a.r+pad<b.l||a.l-pad>b.r||a.b+pad<b.t||a.t-pad>b.b)}
function labelBox(ctx,word,x,y,angle,fontSize){ctx.save();ctx.font='900 '+fontSize+'px Arial';const m=ctx.measureText(word),w=m.width+10,h=fontSize+8;ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='rgba(2,6,10,.78)';ctx.fillRect(-5,-h/2,w,h);ctx.fillStyle='#fff';ctx.textBaseline='middle';ctx.fillText(word,0,0);ctx.restore();return {w,h}}
function smartWords(ctx,text,px,py,c,W,H,occupied){
 const words=String(text||'').replace(/[_\/-]+/g,' ').split(/\s+/).filter(Boolean); if(!words.length)return;
 const fs=Math.max(12,Math.min(18,W/82));
 words.forEach((word,i)=>{
  const baseAngles=[-1.22,-.78,-.38,.18,.58,1.0,-1.55,1.42];
  const baseD=[42,70,102,136,172,210,248,286];
  let placed=false;
  for(let k=0;k<baseAngles.length&&!placed;k++){
   const ang=baseAngles[(i+k)%baseAngles.length];
   const d=baseD[(i+k)%baseD.length]+(i*10);
   let x=clamp(px+Math.cos(ang)*d,35,W-35),y=clamp(py+Math.sin(ang)*d,28,H-28);
   ctx.font='900 '+fs+'px Arial';const tw=ctx.measureText(word).width+16,th=fs+12;
   const box={l:x-tw/2,r:x+tw/2,t:y-th/2,b:y+th/2};
   if(occupied.some(o=>rectHit(box,o,5)))continue;
   ctx.strokeStyle=c;ctx.globalAlpha=.78;ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(x,y);ctx.stroke();ctx.globalAlpha=1;
   labelBox(ctx,word,x,y,ang,fs);occupied.push(box);placed=true;
  }
  if(!placed){const x=clamp(px+20+words.indexOf(word)*18,20,W-20),y=clamp(py-25,20,H-20);labelBox(ctx,word,x,y,baseAngles[i%baseAngles.length],fs)}
 })
}
function drawZone(ctx,o,X,Y,X2,Y2,c,label,W,H,occupied){
 const l=Math.min(X,X2),t=Math.min(Y,Y2),ww=Math.max(4,Math.abs(X2-X)),hh=Math.max(4,Math.abs(Y2-Y));ctx.globalAlpha=.13;ctx.fillStyle=c;ctx.fillRect(l,t,ww,hh);ctx.globalAlpha=.95;ctx.strokeStyle=c;ctx.lineWidth=3;ctx.setLineDash([8,5]);ctx.strokeRect(l,t,ww,hh);ctx.setLineDash([]);smartWords(ctx,label,l+ww/2,t+hh/2,c,W,H,occupied);ctx.globalAlpha=1
}
function drawTrend(ctx,X,Y,X2,Y2,c,label,W,H,occupied){ctx.strokeStyle=c;ctx.lineWidth=4;ctx.setLineDash([13,7]);ctx.beginPath();ctx.moveTo(X,Y);ctx.lineTo(X2,Y2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=c;ctx.beginPath();ctx.arc(X,Y,5,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(X2,Y2,5,0,Math.PI*2);ctx.fill();smartWords(ctx,label||'TREND LINE',X2,Y2,c,W,H,occupied)}
function drawStructureLine(ctx,o,W,H,c,occupied){const X=(+o.x||0)*W,Y=(+o.y||0)*H,X2=o.x2==null?W:(+o.x2)*W,Y2=o.y2==null?Y:(+o.y2)*H;ctx.strokeStyle=c;ctx.lineWidth=2;ctx.setLineDash([6,5]);ctx.beginPath();ctx.moveTo(X,Y);ctx.lineTo(X2,Y2);ctx.stroke();ctx.setLineDash([]);smartWords(ctx,o.label||o.type,X,Y,c,W,H,occupied)}
function annotate(src,a){return new Promise(resolve=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),W=Math.min(1800,im.naturalWidth),H=Math.round(im.naturalHeight*(W/im.naturalWidth));c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.drawImage(im,0,0,W,H);const occupied=[];const anns=a.annotations||[];
 anns.forEach(o=>{const X=(+o.x||0)*W,Y=(+o.y||0)*H,X2=o.x2==null?null:(+o.x2)*W,Y2=o.y2==null?null:(+o.y2)*H,C=colorFor(o.type),type=String(o.type||'').toUpperCase(),label=o.label||type;
  if(type==='TRENDLINE'||type==='TREND_UP'||type==='TREND_DOWN'){drawTrend(ctx,X,Y,X2??X+W*.2,Y2??Y,C,label,W,H,occupied);return}
  if(type==='FVG'||type==='OB_BULL'||type==='OB_BEAR'||type==='LIQUIDITY_ZONE'){if(X2!=null&&Y2!=null)drawZone(ctx,o,X,Y,X2,Y2,C,label,W,H,occupied);else{ctx.fillStyle=C;ctx.globalAlpha=.2;ctx.fillRect(X-20,Y-18,80,36);ctx.globalAlpha=1;smartWords(ctx,label,X,Y,C,W,H,occupied)}return}
  if((type==='SUPPORT'||type==='RESISTANCE')&&X2!=null&&Y2!=null){drawStructureLine(ctx,o,W,H,C,occupied);return}
  ctx.fillStyle=C;ctx.beginPath();ctx.arc(X,Y,7,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#02060a';ctx.lineWidth=2;ctx.stroke();smartWords(ctx,label,X,Y,C,W,H,occupied);
 });
 const p=a.path||[];for(let i=1;i<p.length;i++){const q1=p[i-1],q2=p[i],c=q2.direction==='DOWN'?'#ff6378':q2.direction==='UP'?'#27e0a0':'#ffd166';const x1=q1.x*W,y1=q1.y*H,x2=q2.x*W,y2=q2.y*H;ctx.strokeStyle=c;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();const ang=Math.atan2(y2-y1,x2-x1),s=13;ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-s*Math.cos(ang-.45),y2-s*Math.sin(ang-.45));ctx.lineTo(x2-s*Math.cos(ang+.45),y2-s*Math.sin(ang+.45));ctx.closePath();ctx.fill();smartWords(ctx,q2.label||'PATH',x2,y2,c,W,H,occupied)}
 resolve(c.toDataURL('image/jpeg',.92))};im.src=src})}
function tutorialHtml(q){const t=q.tutorial||[],cs=q.concepts||[];let h='';if(cs.length)h+='<div class="tutorialBox"><div class="sectionTitle">CONCEPTS — WHAT + WHY</div>'+cs.map(z=>'<div class="concept"><b>'+esc(z.name)+'</b><br><b>WHAT:</b> '+esc(z.what)+'<br><b>WHY:</b> '+esc(z.why)+'</div>').join('')+'</div>';if(t.length)h+='<div class="tutorialBox"><div class="sectionTitle">STEP-BY-STEP EXPLANATION</div>'+t.map((z,i)=>'<div class="stepLine"><div class="stepNo">'+(i+1)+'</div><div><b>'+esc(z.title)+'</b><br>'+esc(z.text)+'</div></div>').join('')+'</div>';return h}
async function render(d,compressed){document.getElementById('result').style.display='block';const o=d.analysis?.overall||{};document.getElementById('title').textContent=(o.trade_state||'WAIT')+' • '+(o.direction||'NEUTRAL')+' • '+(o.next_move||'WAIT');document.getElementById('confidence').textContent='Evidence confidence: '+(o.confidence??'—')+' / 100';document.getElementById('final').textContent='ENTRY\n'+(o.entry_plan||'WAIT FOR CONFIRMATION')+'\n\nCONFIRMATION\n'+(o.confirmation||'Not defined')+'\n\nINVALIDATION / SL\n'+(o.invalidation||'Not defined')+'\n\nTP1\n'+(o.targets?.tp1||'Not defined')+'\n\nTP2\n'+(o.targets?.tp2||'Not defined');document.getElementById('dEntry').textContent=o.entry_plan||'WAIT';document.getElementById('dConfirm').textContent=o.confirmation||'WAIT';document.getElementById('dInvalid').textContent=o.invalidation||'—';document.getElementById('dTp1').textContent=o.targets?.tp1||'—';document.getElementById('dTp2').textContent=o.targets?.tp2||'—';document.getElementById('current').innerHTML='<b>CURRENT PRICE — THE DECISION ANCHOR</b><br>'+esc(o.current_price_context||'The current rightmost price state was not clearly readable.')+'<div class="scenarioBox"><b>WHY THIS DECISION</b><br>'+esc(o.reason||'Not defined')+'</div>';document.getElementById('reason').textContent=o.risk_note||'';document.getElementById('confluence').innerHTML='<b>CONFLUENCE:</b> '+esc((d.analysis?.confluence||[]).join(' • '));document.getElementById('story').innerHTML=(o.market_story||[]).map((x,i)=>'<div class="storyStep"><b>STEP '+(i+1)+'</b>'+esc(x)+'</div>').join('');const out=document.getElementById('charts');out.innerHTML='';for(let i=0;i<compressed.length;i++){const src=URL.createObjectURL(compressed[i]),q=(d.analysis.charts||[]).find(z=>Number(z.index)===i+1)||(d.analysis.charts||[])[i]||{},img=await annotate(src,q),card=document.createElement('div');card.className='chartCard';card.innerHTML='<div class="chartHead"><b>'+esc(q.timeframe||'CHART '+(i+1))+'</b><span>'+esc(q.role||'')+'<br>'+esc(q.direction||'NEUTRAL')+' • '+esc(q.next_move||'WAIT')+'</span></div>';const wrap=document.createElement('div');wrap.className='chartWrap';const pic=document.createElement('img');pic.className='chartImg';pic.src=img;pic.onclick=()=>openBig(img);wrap.appendChild(pic);card.appendChild(wrap);const ob=q.valid_order_block||{},en=q.entry||{};const inf=document.createElement('div');inf.className='info';inf.innerHTML='<div class="currentBox"><b>● CURRENT PRICE STATE</b><br>'+esc(q.current_state||'Not clearly readable')+'<br><small>'+esc(q.current_price_note||'')+'</small></div><div class="ob"><b>🟢 VALID ORDER BLOCK: '+esc(ob.status||'NONE')+'</b><br>'+esc(ob.why||'No reliable candidate.')+'<br><small>Why nearby alternatives are not selected: '+esc(ob.why_not_others||'Insufficient evidence')+'</small></div><div class="entry"><b>🟡 ENTRY / WATCH ZONE</b><br>'+esc(en.zone||'Not clearly visible')+'<br><small>State: '+esc(en.state||'NONE')+'</small></div><div class="confirm"><b>🔵 CONFIRMATION</b><br>'+esc(en.confirmation||'Wait for confirmation before entry.')+'</div><div class="danger"><b>🔴 INVALIDATION / STOP CONDITION</b><br>'+esc(en.invalidation||'Not defined')+'</div><div class="target"><b>🎯 FORWARD TARGET</b><br>'+esc(en.target||'Not defined')+'</div>'+tutorialHtml(q);card.appendChild(inf);out.appendChild(card)}}
document.getElementById('form').onsubmit=async e=>{e.preventDefault();const err=document.getElementById('err'),btn=document.getElementById('go');err.textContent='';btn.disabled=true;btn.textContent='ANALYZING ALL TIMEFRAMES…';try{const fs=[...document.querySelectorAll('.file')],ts=[...document.querySelectorAll('.tf')],chosen=[];for(let i=0;i<fs.length;i++)if(fs[i].files[0])chosen.push({file:fs[i].files[0],tf:ts[i].value});if(!chosen.length)throw new Error('Choose at least one chart.');const fd=new FormData();fd.append('symbol',document.querySelector('[name="symbol"]').value);for(const x of chosen){fd.append('charts[]',await compress(x.file),x.file.name.replace(/\.[^.]+$/,'')+'.jpg');fd.append('timeframes[]',x.tf)}const r=await fetch('analyze.php',{method:'POST',body:fd});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Analysis failed.');await render(d,chosen.map(x=>new File([x.file],x.file.name,{type:x.file.type})));window.scrollTo({top:document.getElementById('result').offsetTop-10,behavior:'smooth'})}catch(x){err.textContent=x.message||'Analysis failed.'}finally{btn.disabled=false;btn.textContent='ANALYZE ALL TIMEFRAMES'}};
</script>
</body></html>